def _collect_metrics(repo, targets, recursive):
    metrics = collect(
        repo,
        output_filter=lambda o: o.metric,
        targets=targets,
        recursive=recursive,
    )

    for key in metrics:
        if key.scheme != "local":
            raise MetricsError(f"Unsupported metric type: {key.scheme}")

    return [relpath(key.path, repo.root_dir) for key in metrics]


def _read_metrics(repo, metrics, recursive):
    res = {}
    for metric in metrics:
        value = repo.metrics.utils.read_metrics_file(metric)
        if recursive:
            res.update({f"{metric}:{k}": v for k, v in flatten(value).items()})
        else:
            res[metric] = value
    return res


@locked
def show(repo, targets=None, recursive=False):
    metrics = _collect_metrics(repo, targets, recursive)
    return _read_metrics(repo, metrics, recursive)
