@alias('visit_loop', (
    'visit_For',
    'visit_While',
    'visit_AsyncFor',
))
class LoopVisitor(BaseVisitor):
    """Checks loops."""

    def visit_loop(self, node: AnyLoop) -> None:
        """
        Checks loops ...

        """
        self._check_loop_nodes(node)
        self.generic_visit(node)

    def _check_loop_nodes(self, node: AnyLoop) -> None:
        for child in ast.walk(node):
            if isinstance(child, ast.Break):
                self.add_violation(violations.BreakInLoop(child))
            elif isinstance(child, ast.Lambda):
                self._check_lambda(child, node)

    def _check_lambda(self, node: ast.Lambda, loop: AnyLoop) -> None:
        if nodes.get_variables(loop) & nodes.get_variables(node):
            self.add_violation(violations.LambdaInLoop(node))
