def substitute_references(tokens: Iterable[Token]) -> Iterable[Token]:
    """Substitute references (`$var`) in an iterable of tokens.

    Args:
        tokens: Iterable of tokens.

    Raises:
        TokenError: If a reference was found with an illegal name.
        UnresolvedVariableError: If a reference to a variable that has not been defined is found.

    Yields:
        Tokens.
    """
    variables: dict[str, list[Token]] = {}
    name_tokens = {"token", "variable_name"}
    skip_tokens = {"whitespace", "comment", "newline"}
    reference_tokens = {"variable_name"}

    tokens = list(tokens)
    current_reference: list[Token] | None = None
    for token in tokens:
        if current_reference is None:
            if token.name == "variable_name":
                if token.value == "define":
                    current_reference = []
                elif token.value in variables:
                    for variable_token in variables[token.value]:
                        yield variable_token
                else:
                    raise UnresolvedVariableError(token)
            else:
                yield token
        else:
