class FuzzyDict(dict):
    """
    A dictionary that uses fuzzy matching to get keys and values.

    This can be useful in cases where the exact key is not known, but is close
    enough to a key in the dictionary.
    """

    def __init__(self, *args, cutoff=0.8, **kwargs):
        super().__init__(*args, **kwargs)
        self.cutoff = cutoff

    def __getitem__(self, key):
        try:
            return super().__getitem__(key)
        except KeyError as error:
            if key in self.keys():
                return self[key]
            # check for spaces at start and end of key
            stripped_key = key.strip()
            if stripped_key != key:
                try:
                    return super().__getitem__(stripped_key)
                except KeyError:
                    pass
            # provide the best matches
            best_matches = difflib.get_close_matches(
                key, self.keys(), n=3, cutoff=self.cutoff
            )
            raise KeyError(
                f"'{key}' not found. Best matches are {best_matches}. If you "
                "want to check for near-matches, use `pybamm.print_matches(key)`."
            ) from error
```

