    def field2nullable(self, ret: dict, field: fields.Field, **kwargs) -> dict:
        """Add nullable information to schema."""
        if self.openapi_version.major < 3:
            if field.allow_none:
                ret["x-nullable"] = True
        elif self.openapi_version.minor >= 1:
            # in OAS 3.1, nullable is expressed through type
            if field.allow_none:
                if "type" in ret:
